import { test, expect } from '@playwright/test';

// 🤖 Generated by AI: "Write a Playwright test for placing an order in the shop"
test.fixme('test order', async ({ page }) => {
  await page.goto('http://localhost:3000/login');
  await page.fill('#email', 'user@shop.test');
  await page.fill('#password', 'User123!');
  await page.click('button[type="submit"]');

  await page.waitForTimeout(3000);

  await page.click('ul > li:nth-child(2) > button');
  await page.click('text=Checkout');

  await page.getByRole('button', { name: 'Confirm purchase' }).click();

  expect(page.getByText('Thank you for your order!')).toBeVisible();
  expect(page).toBeTruthy();
});
